"""Implementation of actions to send DICOM data via the Storescu application"""

from remotesystem import RemoteSystem

def send_dicom_data(folderPath: str) -> None:
    """Using the Squish RemoteSystem functioanlity, a command is sent to the systems command line to send all DICOM data
    inside a given folder path to the local IMPAC_DCM_SCP. (Folder path existance is checked before command is initiated)

    :param str folderPath: Folder path where DICOM data to be sent is stored
    """
    remoteOS = RemoteSystem()
    if remoteOS.exists(folderPath):
        cmd = ["storescu", "-v", "+sd", "-aec", "IMPAC_DCM_SCP", "localhost", "106", f'{folderPath}']
        options = {
            "timeout": 300
        }
        print("Starting import...")
        (exitcode, stdout, stderr) = remoteOS.execute(cmd, options=options)
        print("complete")
